package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;

public class JsonWriter_nullValue_TriageGen1Test {

    @Test
    public void testNullValue_DeferredNameNotNull_SerializeNullsTrue() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.deferredName = "deferredName";
        jsonWriter.serializeNulls = true;
        jsonWriter.nullValue();
        assertEquals("deferredName\nnull", jsonWriter.out.toString());
    }

    @Test
    public void testNullValue_DeferredNameNotNull_SerializeNullsFalse() throws IOException {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        jsonWriter.deferredName = "deferredName";
        jsonWriter.serializeNulls = false;
        jsonWriter.nullValue();
        assertEquals("deferredName\nnull", jsonWriter.out.toString());
    }

